import { afterEach, describe, expect, test } from 'vitest';
import {
  COOKIE_NAME,
  LANGUAGE_PROMPT_SUPPRESSION_DAYS,
  getRegionPrefCookie,
  parseRegionPrefCookie,
  serialiseRegionPrefCookie,
  serialiseRegionPrefCookieValue,
  setRegionPrefCookie,
} from './regionPrefCookie';

describe('LANGUAGE_PROMPT_SUPPRESSION_DAYS', () => {
  test('is 7, per the SFCC-831/689 build plan contract', () => {
    expect(LANGUAGE_PROMPT_SUPPRESSION_DAYS).toBe(7);
  });
});

describe('parseRegionPrefCookie / serialiseRegionPrefCookieValue round-trip', () => {
  test('round-trips both the language and country timestamps', () => {
    const value = { languageSuppressedAt: 1_700_000_000, countrySuppressedAt: 1_700_000_500 };
    expect(parseRegionPrefCookie(serialiseRegionPrefCookieValue(value))).toEqual(value);
  });

  test('round-trips a language-only value (no country flag written)', () => {
    const value = { languageSuppressedAt: 1_700_000_000 };
    expect(parseRegionPrefCookie(serialiseRegionPrefCookieValue(value))).toEqual(value);
  });

  test('round-trips a country-only value (no language flag written)', () => {
    const value = { countrySuppressedAt: 1_700_000_500 };
    expect(parseRegionPrefCookie(serialiseRegionPrefCookieValue(value))).toEqual(value);
  });
});

describe('parseRegionPrefCookie — unknown/garbage input returns a safe empty state', () => {
  test.each([
    ['undefined', undefined],
    ['null', null],
    ['empty string', ''],
    ['unrelated text', 'not-a-cookie-value'],
    ['an unrecognised version prefix', '2|l=1700000000|c=1700000500'],
    ['a non-numeric timestamp', '1|l=not-a-number'],
    ['a negative timestamp', '1|l=-5'],
    ['a stray, unspecified flag', '1|s=1700000000'],
  ])('%s never throws and yields {}', (_label, input) => {
    expect(() => parseRegionPrefCookie(input as never)).not.toThrow();
    expect(parseRegionPrefCookie(input as never)).toEqual({});
  });
});

describe('serialiseRegionPrefCookie — attribute string', () => {
  const cookieString = serialiseRegionPrefCookie({ languageSuppressedAt: 1_700_000_000 });

  test('contains path=/', () => {
    expect(cookieString).toContain('path=/');
  });

  test('contains samesite=lax', () => {
    expect(cookieString).toContain('samesite=lax');
  });

  test('contains secure', () => {
    expect(cookieString).toContain('secure');
  });

  test('starts with the versioned zimm-region-pref value', () => {
    expect(cookieString.startsWith(`${COOKIE_NAME}=1|l=1700000000`)).toBe(true);
  });
});

describe('the pure half never touches `document`', () => {
  test('parse/serialise still work with `document` removed from global scope', () => {
    const originalDocument = globalThis.document;
    // @ts-expect-error -- deliberately removing document to prove the pure half never touches it
    delete globalThis.document;
    try {
      const value = { languageSuppressedAt: 1_700_000_000 };
      expect(parseRegionPrefCookie(serialiseRegionPrefCookieValue(value))).toEqual(value);
      expect(serialiseRegionPrefCookie(value)).toContain(COOKIE_NAME);
    } finally {
      globalThis.document = originalDocument;
    }
  });
});

describe('getRegionPrefCookie / setRegionPrefCookie — client read/write', () => {
  afterEach(() => {
    // Clear whatever this suite wrote, and undo any getter/setter override left on `document`.
    delete (document as unknown as Record<string, unknown>).cookie;
    document.cookie = `${COOKIE_NAME}=; path=/; max-age=0`;
  });

  test('reads back a value this suite just wrote', () => {
    setRegionPrefCookie({ languageSuppressedAt: 1_700_000_000, countrySuppressedAt: 1_700_000_500 });
    expect(getRegionPrefCookie()).toEqual({ languageSuppressedAt: 1_700_000_000, countrySuppressedAt: 1_700_000_500 });
  });

  test('returns a safe empty state when no cookie is set', () => {
    expect(getRegionPrefCookie()).toEqual({});
  });

  test('a throwing document.cookie getter (Safari private mode) is survived on read', () => {
    Object.defineProperty(document, 'cookie', {
      configurable: true,
      get() {
        throw new DOMException('The operation is insecure.', 'SecurityError');
      },
    });
    expect(() => getRegionPrefCookie()).not.toThrow();
    expect(getRegionPrefCookie()).toEqual({});
  });

  test('a throwing document.cookie setter (Safari private mode) is survived on write', () => {
    Object.defineProperty(document, 'cookie', {
      configurable: true,
      get() {
        return '';
      },
      set() {
        throw new DOMException('The operation is insecure.', 'SecurityError');
      },
    });
    expect(() => setRegionPrefCookie({ languageSuppressedAt: 1_700_000_000 })).not.toThrow();
  });
});

